Code: Bargeld und Giralgeld (FRED)

# Daten: FRED (St. Louis Fed), einmal laden und als CSV neben der qmd speichern
get_fred &lt;- function(id) {
  f &lt;- paste0("fred_", id, ".csv")
  if (!file.exists(f)) {
    try(download.file(
      paste0("https://fred.stlouisfed.org/graph/fredgraph.csv?id=", id),
      f, mode = "wb", quiet = TRUE), silent = TRUE)
  }
  if (!file.exists(f)) return(NULL)
  d &lt;- read.csv(f)
  names(d) &lt;- c("date", "value")
  d$date  &lt;- as.Date(d$date)
  d$value &lt;- suppressWarnings(as.numeric(d$value))
  d[!is.na(d$value), ]
}

cur &lt;- get_fred("CURRCIR")   # Bargeld im Umlauf (Mrd. USD)
m2  &lt;- get_fred("M2SL")      # Geldmenge M2 (Mrd. USD)

if (is.null(cur) || is.null(m2)) {
  cat("Daten konnten nicht geladen werden.")
} else {
  yrs &lt;- c(1960, 1980, 2000, 2025)

  d &lt;- inner_join(rename(cur, bar = value), rename(m2, m2 = value), by = "date") |&gt;
    mutate(year = as.integer(format(date, "%Y"))) |&gt;
    filter(year %in% yrs) |&gt;
    group_by(year) |&gt;
    summarise(bar = mean(bar), m2 = mean(m2), .groups = "drop") |&gt;
    mutate(Giralgeld = m2 - bar,
           panel = factor(paste0(year, ": ", round(100 * bar / m2), " % Bargeld"),
                          levels = paste0(year, ": ", round(100 * bar / m2), " % Bargeld"))) |&gt;
    select(panel, Bargeld = bar, Giralgeld) |&gt;
    pivot_longer(c(Bargeld, Giralgeld), names_to = "art", values_to = "wert")

  p &lt;- ggplot(d, aes(y = wert, fill = art)) +
    geom_pemwaffle(stack_order = c("Bargeld", "Giralgeld")) +
    facet_wrap(~panel, nrow = 2) +
    coord_equal() +
    scale_y_reverse() +
    scale_fill_manual(values = c(Bargeld = "#e76254", Giralgeld = "#5d8198"),
                      name = NULL) +
    labs(title = "Bargeld ist nur ein Teil des Geldes",
         subtitle = "1 Kachel = 1 % der Geldmenge M2 (USA)",
         caption = "Quelle: FRED (CURRCIR, M2SL), Jahresdurchschnitte") +
    theme_void(base_size = 14) +
    theme(
      plot.background  = element_rect(fill = "transparent", colour = NA),
      panel.background = element_rect(fill = "transparent", colour = NA),
      plot.title    = element_text(colour = "#343a40", face = "bold", hjust = 0),
      plot.subtitle = element_text(colour = "#868e96", hjust = 0,
                                   margin = margin(b = 8)),
      plot.caption  = element_text(colour = "#868e96", size = 9, hjust = 0),
      strip.text    = element_text(colour = "#343a40", face = "bold",
                                   margin = margin(b = 4)),
      legend.position = "bottom",
      legend.text = element_text(colour = "#495057")
    )
  print(p)
}
